enum Msg {
    Move { x: i32, y: i32 },
    Write(String),
    Quit,
}

fn run(m: &Msg) -> i32 {
    match m {
        Msg::Move { x, y: 0 } => *x,
        Msg::Move { x, y } if x == y => x * 10,
        Msg::Move { .. } => -1,
        Msg::Write(s) if s.len() > 2 => s.len() as i32,
        _ => 0,
    }
}

fn main() {
    let a = run(&Msg::Move { x: 5, y: 0 });
    let b = run(&Msg::Move { x: 4, y: 4 });
    let c = run(&Msg::Move { x: 1, y: 2 });
    let d = run(&Msg::Write(String::from("hey")));
    let e = run(&Msg::Quit);
    println!("{a} {b} {c} {d} {e}");
}
